return items.map(item => {
  const md = item.json.markdown;

  // 1. Find the “jobs added recently” header line dynamically (case‑insensitive)
  const splitRegex = /^#{1,3}\s*.+jobs added recently\s*$/im;
  // Split into [introSection, jobsSection]
  const parts = md.split(splitRegex);
  const introSectionRaw = parts[0] || '';
  const jobsSectionRaw = parts.slice(1).join('') || '';

  // 2. Clean up the intro text
  const intro = introSectionRaw
    .replace(/^#+\s*/gm, '') // strip any leading “#” headings
    .trim();

  // 3. Extract each job title + link (ignore image‑only links)
  const jobs = [];
  const re = /\-\s*\[(?!\!)([^\]]+)\]\((https?:\/\/[^\)]+)\)/g;
  let match;
  while ((match = re.exec(jobsSectionRaw))) {
    jobs.push({
      title: match[1].trim(),
      link:  match[2].trim(),
    });
  }

  // 4. Return a new item
  return {
    json: {
      intro,
      jobs,
    },
  };
});

const output = [];

items.forEach(item => {
  const intro = item.json.intro;
  const jobs  = item.json.jobs || [];

  jobs.forEach(job => {
    output.push({
      json: {
        intro,             
        jobTitle: job.title,
        jobLink:  job.link
      }
    });
  });
});

return output;
